-- HD2-Addon: mods/tongz/senator_talon_crosshair
local layout_resolver=(function()
-- Read-only game.dll global-pointer resolver for post-update layout migration.
local ffi,bit=require('ffi'),require('bit')
local M={}

local function u16(s,o)local a,b=s:byte(o+1,o+2);return b and a+b*256 or nil end
local function u32(s,o)local a,b,c,d=s:byte(o+1,o+4);return d and a+b*256+c*65536+d*16777216 or nil end
local function u64(s,o)
    local lo,hi=u32(s,o),u32(s,o+4);if not hi then return nil end
    local n=lo+hi*4294967296
    return n>=65536 and n<0x800000000000 and n or nil
end
local function power2(n)return n and n>0 and bit.band(n,n-1)==0 end

local function lookup(api,manager,key,limit)
    local h=api.read(manager+32,20);if not h then return nil end
    local data,cap,empty,mult=u64(h,0),u32(h,8),u32(h,12),u32(h,16)
    if not data or not power2(cap) or cap>limit then return nil end
    local product=tonumber(ffi.cast('uint32_t',ffi.new('uint64_t',key)*ffi.new('uint64_t',mult)))
    for probe=0,math.min(cap,128)-1 do
        local row=api.read(data+8*bit.band(product+probe,cap-1),8);if not row then return nil end
        local found,index=u32(row,0),u32(row,4)
        if found==key then return index~=0xffffffff and index or nil end
        if found==empty then return nil end
    end
end

local function map_header(api,address,offset,limit)
    local b=api.read(address+offset,20);if not b then return nil end
    local data,cap,empty,mult=u64(b,0),u32(b,8),u32(b,12),u32(b,16)
    if not data or not power2(cap) or cap>limit or not empty or not mult or mult==0 then return nil end
    local r=api.query(data)
    if not r or not r.readable then return nil end
    return {data=data,cap=cap,empty=empty,mult=mult}
end

local function valid_settings(api,address)
    local head=api.read(address,32)
    if not head or u32(head,0)~=11 or u32(head,4)~=0x444c444c
        or u32(head,8)~=1 or u32(head,12)~=0x30eb6399 then return nil end
    local source=api.read_blob(address,79296);if not source then return nil end
    local offset,ids=4,{}
    for _=1,11 do
        if u32(source,offset)~=0x444c444c or u32(source,offset+4)~=1
            or u32(source,offset+8)~=0x30eb6399 then return nil end
        local root=offset+24;local size,count=u32(source,offset+12),u32(source,root+8)
        local items=u64(source,root)
        if not size or not count or count<1 or count>148 or not items then return nil end
        local finish,start=root+size,items-address
        if finish>#source or start<root+16 or start>finish then return nil end
        for i=0,count-1 do
            local ro=start+i*400
            if ro+400<=finish then
                local id=u32(source,ro+4)
                if id==1813634375 then ids.eat=true end
                if id==1979913877 then ids.eagle=true end
            end
        end
        offset=finish
    end
    if offset~=#source then return nil end
    return ids.eat and ids.eagle and 'SETTINGS_EAT_AND_EAGLE' or 'SETTINGS_STRUCTURE_ONLY'
end

local function classify(api,address)
    local out={}
    local region=api.query(address)
    if not region or not region.readable or region.kind~=0x20000 then return out end
    if region.base+region.size-address>=79296 then
        local settings=valid_settings(api,address);if settings then out[#out+1]=settings end
    end
    if region.base+region.size-address>=0xf31af0 then
        local owner_map=map_header(api,address,0xf21a88,1048576)
        local entity=api.read(address+0xf31ad8,24)
        if owner_map and entity then out[#out+1]='ENTITY_OWNER' end
    end
    local equipment=map_header(api,address,40,8192)
    local equipment_rows=api.pointer(api.read(address+80,8))
    if equipment and equipment_rows then out[#out+1]='EQUIPMENT_MANAGER' end
    local attachment=map_header(api,address,32,8192)
    local attachment_rows=api.pointer(api.read(address+64,8))
    if attachment and attachment_rows then out[#out+1]='ATTACHMENT_MANAGER' end
    local avatar=map_header(api,address,0xf8,64)
    local avatar_count=u32(api.read(address+0x6c,4)or'',0)
    if avatar and avatar_count and avatar_count<=8 then out[#out+1]='AVATAR_MANAGER' end
    local counts=api.read(address+0x84,8)
    local unit=api.read(address+0x3a8,4)
    local player_list=api.pointer(api.read(address+0xe8,8))
    if counts and unit and player_list then
        local a,b=u32(counts,0),u32(counts,4)
        if a and b and a<=64 and b<=64 and u32(unit,0)<=0x7fff then out[#out+1]='PLAYER_MANAGER' end
    end
    local mode=api.read(address,0x44)
    if mode then
        local active,mission=u32(mode,8),u32(mode,0x40)
        if (active==0 or active==1) and mission and mission<=7 then out[#out+1]='MISSION_MODE' end
    end
    return out
end

M.classify=classify
function M.new(api,game)
    local dos=assert(api.read(game,0x100),'game_header_unreadable')
    assert(u16(dos,0)==0x5a4d,'game_mz_invalid')
    local peoff=assert(u32(dos,0x3c),'game_pe_offset_missing')
    local nt=assert(api.read(game+peoff,0x100),'game_nt_header_unreadable')
    assert(u32(nt,0)==0x4550,'game_pe_invalid')
    local image_size=assert(u32(nt,0x50),'game_image_size_missing')
    assert(image_size>0x100000 and image_size<0x10000000,'game_image_size_invalid')
    local s={status='WAITING_FOR_MISSION',writes=0,image_size=image_size,offset=0,
        bytes=0,regions=0,pointers=0,candidates={},seen={},tested={},frames=0,pool={}}
    local function add(kind,rva,address)
        local key=kind..':'..string.format('%X',rva)
        if s.seen[key] then return end
        s.seen[key]=true;s.pool[kind]=s.pool[kind]or{}
        if #s.pool[kind]<4096 then s.pool[kind][#s.pool[kind]+1]={kind=kind,rva=rva,address=address}end
    end
    local function emit(kind,item,detail)
        s.candidates[#s.candidates+1]={kind=kind,rva=item.rva,address=item.address,detail=detail}
    end
    local function finalize()
        s.candidates={}
        local owners=s.pool.ENTITY_OWNER or{}
        for _,v in ipairs(owners)do emit('ENTITY_OWNER',v,'STRUCTURE_ANCHOR')end
        for _,v in ipairs(s.pool.SETTINGS_EAT_AND_EAGLE or{})do emit('SETTINGS_BUFFER',v,'EAT_AND_EAGLE_VERIFIED')end
        if #owners~=1 then s.status='COMPLETE_OWNER_NOT_UNIQUE_'..#owners;return end
        local owner=owners[1].address
        local avatar_identity=('97FA4D294D331C4D'):gsub('..',function(x)return string.char(tonumber(x,16))end)
        local verified_players={}
        for _,v in ipairs(s.pool.PLAYER_MANAGER or{})do
            local counts,unitb=api.read(v.address+0x84,8),api.read(v.address+0x3a8,4)
            local unit=unitb and u32(unitb,0)
            if counts and unit and unit<0x7fff and u32(counts,0)>0 and u32(counts,4)>0 then
                local index=lookup(api,owner+0xf21a68,unit,1048576)
                local entity=index and api.read(owner+0xf31ad8+index*24,24)
                if entity and entity:sub(1,8)==avatar_identity then
                    verified_players[#verified_players+1]={item=v,avatar=u32(entity,8),entity=entity}
                    emit('PLAYER_MANAGER',v,'OWNER_AVATAR_VERIFIED')
                end
            end
        end
        if #verified_players==1 then
            local avatar,entity=verified_players[1].avatar,verified_players[1].entity
            for _,v in ipairs(s.pool.EQUIPMENT_MANAGER or{})do
                local index=lookup(api,v.address+8,avatar,8192)
                local rows=api.pointer(api.read(v.address+80,8))
                if index and rows and index<4096 then
                    local row=api.read(rows+index*48,48)
                    if row then emit('EQUIPMENT_MANAGER',v,'AVATAR_ID_VERIFIED')end
                end
            end
            for _,v in ipairs(s.pool.AVATAR_MANAGER or{})do
                local index=lookup(api,v.address+0xd8,avatar,64)
                local count=u32(api.read(v.address+0x6c,4)or'',0)
                local rows=index and api.pointer(api.read(v.address+0x110+index*8,8))
                if index and count and index<count and rows and api.read(rows,24)==entity then
                    emit('AVATAR_MANAGER',v,'AVATAR_OWNER_VERIFIED')
                end
            end
        end
        local modes={}
        for _,v in ipairs(s.pool.MISSION_MODE or{})do
            local b=api.read(v.address,0x44);local active=b and u32(b,8);local mission=b and u32(b,0x40)
            if active==1 and mission and mission>=1 and mission<=7 then modes[#modes+1]=v end
        end
        if #modes==1 then emit('MISSION_MODE',modes[1],'ACTIVE_MISSION_UNIQUE')end
        s.status='COMPLETE_CORRELATED'
    end
    function s:step()
        self.frames=self.frames+1
        if self.frames<300 or self.status:find('^COMPLETE') or self.status=='ERROR' then return end
        self.status='SCANNING_GAME_IMAGE'
        -- One 64 KiB image chunk per frame keeps the resolver read-only and
        -- limits its impact while a mission is running.
        local budget=1
        while budget>0 and self.offset<self.image_size do
            budget=budget-1
            local address=game+self.offset;local region=api.query(address)
            if not region then self.offset=self.offset+0x10000
            else
                local finish=math.min(game+self.image_size,region.base+region.size)
                local start=math.max(address,region.base)
                local size=math.min(65536,finish-start)
                if (region.readable or region.kind==0x1000000) and size>=8 then
                    local bytes=region.kind==0x1000000 and api.read_module(start,size) or api.read_blob(start,size)
                    if bytes then
                        self.regions=self.regions+1;self.bytes=self.bytes+#bytes
                        local base_rva=start-game
                        local first=(8-(base_rva%8))%8
                        for o=first,#bytes-8,8 do
                            local pointer=u64(bytes,o)
                            if pointer and not self.tested[pointer] and not api.excluded(pointer,8) then
                                self.tested[pointer]=true;self.pointers=self.pointers+1
                                local kinds=classify(api,pointer)
                                for _,kind in ipairs(kinds)do add(kind,base_rva+o,pointer)end
                            end
                        end
                    end
                end
                self.offset=start-game+math.max(size,0x1000)
            end
        end
        if self.offset>=self.image_size then finalize();if self.status=='SCANNING_GAME_IMAGE'then self.status='COMPLETE_CORRELATED'end end
    end
    return s
end
return M

end)()
local create_api=(function()
-- Windows API adapter for a single, guarded GL-28 capacity change.
return function()
    local ffi=require('ffi')
    assert(ffi.os=='Windows' and ffi.abi('64bit'),'windows_x64_required')
    ffi.cdef[[
        void *GetModuleHandleA(const char *);
        uint32_t GetModuleFileNameW(void *,uint16_t *,uint32_t);
        void *GetCurrentProcess(void);
        int ReadProcessMemory(void *,const void *,void *,size_t,size_t *);
        int WriteProcessMemory(void *,void *,const void *,size_t,size_t *);
        size_t VirtualQuery(const void *,void *,size_t);
        int VirtualProtect(void *,size_t,uint32_t,uint32_t *);
        uint32_t GetLastError(void);
        void *CreateFileW(const uint16_t *,uint32_t,uint32_t,void *,uint32_t,uint32_t,void *);
        int ReadFile(void *,void *,uint32_t,uint32_t *,void *);
        int CloseHandle(void *);
        int32_t BCryptOpenAlgorithmProvider(void **,const uint16_t *,const uint16_t *,uint32_t);
        int32_t BCryptCreateHash(void *,void **,void *,uint32_t,const void *,uint32_t,uint32_t);
        int32_t BCryptHashData(void *,const void *,uint32_t,uint32_t);
        int32_t BCryptFinishHash(void *,void *,uint32_t,uint32_t);
        int32_t BCryptDestroyHash(void *);
        int32_t BCryptCloseAlgorithmProvider(void *,uint32_t);
        typedef struct { void *base; void *allocation; uint32_t protection0;
            uint16_t partition; uint16_t reserved; size_t size;
            uint32_t state; uint32_t protection; uint32_t kind; } TongzCapacityRegion;
    ]]
    local k,b=ffi.load('kernel32'),ffi.load('bcrypt')
    local process=k.GetCurrentProcess()
    local api={}
    local scan_buffer=ffi.new('uint8_t[262144]')
    local scan_count=ffi.new('size_t[1]')
    local scan_address=tonumber(ffi.cast('uintptr_t',scan_buffer))
    function api.excluded(address,size)
        return address<scan_address+262144 and address+size>scan_address
    end
    function api.query(address)
        if address>=0x800000000000 then return nil,'end' end
        local info=ffi.new('TongzCapacityRegion[1]')
        if k.VirtualQuery(ffi.cast('void *',address),info,ffi.sizeof(info[0]))~=ffi.sizeof(info[0]) then
            return nil,k.GetLastError()==87 and 'end' or 'query_failed'
        end
        local r=info[0]
        local p=tonumber(r.protection)%256
        local kind=tonumber(r.kind)
        return {base=tonumber(ffi.cast('uintptr_t',r.base)),allocation=tonumber(ffi.cast('uintptr_t',r.allocation)),size=tonumber(r.size),
            protection=tonumber(r.protection),
            readable=r.state==0x1000 and (kind==0x20000 or kind==0x40000)
                and (p==2 or p==4 or p==8 or p==32 or p==64 or p==128)
                and tonumber(r.protection)<256,kind=kind}
    end
    function api.read_blob(address,size)
        if type(size)~='number' or size<=0 or size>262144 or api.excluded(address,size) then return nil end
        local r=api.query(address)
        if not r or not r.readable or address<r.base or address+size>r.base+r.size then return nil end
        if k.ReadProcessMemory(process,ffi.cast('const void *',address),scan_buffer,size,scan_count)==0
            or tonumber(scan_count[0])~=size then return nil end
        return ffi.string(scan_buffer,size)
    end
    -- Read-only bulk access for committed module-image pages. General memory
    -- scanners intentionally exclude MEM_IMAGE; layout migration needs to
    -- inspect game.dll's own global-pointer slots without enabling writes.
    function api.read_module(address,size)
        if type(size)~='number' or size<=0 or size>262144 or api.excluded(address,size) then return nil end
        local r=api.query(address)
        if not r or r.kind~=0x1000000 or address<r.base or address+size>r.base+r.size
            or r.protection>=256 then return nil end
        local p=r.protection%256
        if p~=2 and p~=4 and p~=8 and p~=32 and p~=64 and p~=128 then return nil end
        if k.ReadProcessMemory(process,ffi.cast('const void *',address),scan_buffer,size,scan_count)==0
            or tonumber(scan_count[0])~=size then return nil end
        return ffi.string(scan_buffer,size)
    end
    function api.module(name)
        local p=k.GetModuleHandleA(name)
        if p==nil or p==ffi.NULL then return nil end
        return tonumber(ffi.cast('uintptr_t',p))
    end
    local pointer_buffer=ffi.new('uint64_t[1]')
    function api.pointer(bytes)
        if not bytes or #bytes~=8 then return nil end
        ffi.copy(pointer_buffer,bytes,8)
        local p=pointer_buffer[0]
        if p<65536 or p>=0x800000000000 then return nil end
        return tonumber(p)
    end
    local function region(address,size)
        if type(address)~='number' or type(size)~='number' or size<=0
            or address<65536 or address+size>=0x800000000000 then return nil end
        local info=ffi.new('TongzCapacityRegion[1]')
        if k.VirtualQuery(ffi.cast('void *',address),info,ffi.sizeof(info[0]))~=ffi.sizeof(info[0]) then return nil end
        local r=info[0]
        local base=tonumber(ffi.cast('uintptr_t',r.base))
        local protection=tonumber(r.protection)
        if r.state~=0x1000 or address<base or address+size>base+tonumber(r.size)
            or (r.kind~=0x20000 and r.kind~=0x40000 and r.kind~=0x1000000)
            or protection>=256 then return nil end
        return protection,tonumber(r.kind)
    end
    -- AIO: plain reads use ReadProcessMemory alone, like the other modules (it
    -- fails whole on guard, no-access and free pages); region() still gates writes.
    local read_out,read_count=ffi.new('uint8_t[4096]'),ffi.new('size_t[1]')
    function api.read(address,size)
        if type(address)~='number' or type(size)~='number' or size<=0 or size>4096
            or address<65536 or address+size>=0x800000000000 then return nil end
        if k.ReadProcessMemory(process,ffi.cast('const void *',address),read_out,size,read_count)==0
            or tonumber(read_count[0])~=size then return nil end
        return ffi.string(read_out,size)
    end
    function api.write(address,bytes)
        if type(bytes)~='string' or (#bytes~=1 and #bytes~=4 and #bytes~=8 and #bytes~=12
            and #bytes~=16 and #bytes~=24 and #bytes~=268) then
            return false,'invalid_size'
        end
        local protection,kind=region(address,#bytes)
        -- PAGE_WRITECOPY (8) is a non-executable data page used by some
        -- runtime resource snapshots. Allow it with the same guarded
        -- VirtualProtect/write/readback path as PAGE_READONLY.
        if (protection~=2 and protection~=4 and protection~=8) or kind==0x1000000 then
            return false,'not_plain_data_page'
        end
        local before=api.read(address,#bytes)
        if not before then return false,'before_read_failed' end
        local changed=false
        local old=ffi.new('uint32_t[1]')
        if protection~=4 then
            if k.VirtualProtect(ffi.cast('void *',address),#bytes,4,old)==0 then
                return false,'make_writable_failed_'..tonumber(k.GetLastError())
            end
            changed=true
        end
        local count=ffi.new('size_t[1]')
        local ok=k.WriteProcessMemory(process,ffi.cast('void *',address),bytes,#bytes,count)~=0
            and tonumber(count[0])==#bytes
        local write_error=ok and 0 or tonumber(k.GetLastError())
        local restored=true
        if changed then
            local ignored=ffi.new('uint32_t[1]')
            restored=k.VirtualProtect(ffi.cast('void *',address),#bytes,old[0],ignored)~=0
        end
        local after=api.read(address,#bytes)
        return ok and restored and after==bytes,
            string.format('written=%d error=%d restored=%s readback=%s',
                tonumber(count[0]),write_error,tostring(restored),tostring(after==bytes))
    end
    function api.module_hash(address)
        local cache=rawget(_G,'SuzukaShootingModuleHashes')
        if not cache then
            cache={values={},hits=0,misses=0}
            rawset(_G,'SuzukaShootingModuleHashes',cache)
        end
        local verified=cache.values[address]
        if verified then cache.hits=cache.hits+1;return verified end
        cache.misses=cache.misses+1
        local cached=rawget(_G,'TongzVerifiedGameDllHash')
        if type(cached)=='table' and cached.address==address
            and type(cached.sha256)=='string' and #cached.sha256==64 then
            cache.values[address]=cached.sha256;return cached.sha256
        end
        local path=ffi.new('uint16_t[32768]')
        local n=k.GetModuleFileNameW(ffi.cast('void *',address),path,32768)
        assert(n>0 and n<32768,'game_dll_path_unavailable')
        local file=k.CreateFileW(path,0x80000000,7,nil,3,0x08000000,nil)
        assert(file~=ffi.cast('void *',-1),'game_dll_file_unavailable')
        local algorithm,hash=ffi.new('void *[1]'),ffi.new('void *[1]')
        local ok,result=pcall(function()
            local name=ffi.new('uint16_t[7]',{83,72,65,50,53,54,0})
            assert(b.BCryptOpenAlgorithmProvider(algorithm,name,nil,0)==0,'sha256_provider')
            assert(b.BCryptCreateHash(algorithm[0],hash,nil,0,nil,0,0)==0,'sha256_create')
            local chunk,count=ffi.new('uint8_t[65536]'),ffi.new('uint32_t[1]')
            local total=0
            while true do
                assert(k.ReadFile(file,chunk,65536,count,nil)~=0,'game_dll_read')
                if count[0]==0 then break end
                total=total+tonumber(count[0])
                assert(total<=64*1024*1024,'game_dll_too_large')
                assert(b.BCryptHashData(hash[0],chunk,count[0],0)==0,'sha256_update')
            end
            local digest,parts=ffi.new('uint8_t[32]'),{}
            assert(b.BCryptFinishHash(hash[0],digest,32,0)==0,'sha256_finish')
            for i=0,31 do parts[#parts+1]=string.format('%02x',digest[i]) end
            return table.concat(parts)
        end)
        if hash[0]~=nil then b.BCryptDestroyHash(hash[0]) end
        if algorithm[0]~=nil then b.BCryptCloseAlgorithmProvider(algorithm[0],0) end
        k.CloseHandle(file)
        assert(ok,result)
        rawset(_G,'TongzVerifiedGameDllHash',{address=address,sha256=result})
        cache.values[address]=result
        return result
    end
    return api
end

end)()
local KNOWN_GAME_SHA="2e2c3b7c2500646dadd5f2b4c6e0504dbb7e7896139f64cddc0d1813c718f51e"
-- AIO: WEAPON and LASER share one adapter and one entity-owner search. On the
-- hash-verified build the known EntityOwner global is classified first and the
-- game.dll image scan is skipped; any other build or a failed check scans as before.
local shared_api,shared_owner
local function get_api() shared_api=shared_api or create_api();return shared_api end
local function owner_resolver(api,game,state)
    local real=shared_owner or layout_resolver.new(api,game)
    shared_owner=real
    local proxy=setmetatable({},{__index=real})
    function proxy:step()
        -- One block drives the shared search; the other takes over if it stops.
        local driver=real.driver
        if driver and driver~=state and driver.status=='LOCATING_ENTITY_OWNER' then return end
        real.driver=state
        if not real.known_checked and real.frames>=299 then
            real.known_checked=true
            if state.game_sha256==KNOWN_GAME_SHA then
                local owner=api.pointer(api.read(game+0x3326b90,8))
                for _,kind in ipairs(owner and layout_resolver.classify(api,owner) or {}) do
                    if kind=='ENTITY_OWNER' then
                        real.frames=real.frames+1
                        real.candidates={{kind='ENTITY_OWNER',rva=0x3326b90,address=owner,detail='KNOWN_BUILD_GLOBAL'}}
                        real.status='COMPLETE_KNOWN_BUILD';return
                    end
                end
            end
        end
        real:step()
    end
    return proxy
end
local crosshair_settings={amr=true,pistols=true,handling=true,dirty=false}
local function crosshair_menu()
 if crosshair_settings.registered then return end
 local menu=rawget(_G,'ModOptionsMenu')
 if not menu then return end
 if menu.api~=1 or type(menu.register_option)~='function'
  or type(menu.get)~='function' or type(menu.on_change)~='function' then
  crosshair_settings.registered='INCOMPATIBLE';return
 end
 for _,option in ipairs({
  {key='amr',label='ANTI-MATERIEL RIFLE CROSSHAIR',description='Show the APW-1 crosshair outside the scope. OFF restores the original crosshair settings.'},
  {key='pistols',label='SENATOR / TALON NORMAL CROSSHAIR',description='Replace the triangular reticle with the normal reticle. Independent of laser attachments and handling boosts.'},
  {key='handling',id='suzuka_better_shooting.pistol_stat_boost',label='PISTOL STAT BOOST',description='Senator / Talon: ergonomics +10; sway and scope sway multipliers 1 to 0.85. OFF restores native values. Crosshairs and lasers are independent.'}
 }) do
  local key=option.key
