local function report()
 pcall(function()
  local f = loader and loader.open_log and loader.open_log('TongzSenatorTalonWEAPON.log')
  if not f then return end
  f:write('STATUS='..state.status..'\nWRITES='..state.writes..'\nCHECKED_SLOTS='..state.checked..'\n')
  if state.game_sha256 then f:write('GAME_SHA256='..state.game_sha256..'\n') end
  if state.error then f:write('ERROR='..state.error..'\n') end
  f:close()
 end)
end

local function splice(row, offset, bytes)
 return row:sub(1, offset)..bytes..row:sub(offset+#bytes+1)
end
for _,record in ipairs(records) do
 assert(#record.original==1232)
 local target=record.original
 for _,edit in ipairs(record.edits) do target=splice(target,edit.offset,edit.bytes) end
 record.target=target
end

local function crosshair_targets()
 for _,record in ipairs(records) do
  if not record.base_edits then
   record.base_edits=record.edits
   if record.name~='APW-1' then
    record.crosshair_key='pistols'
    record.crosshair_edits={{offset=400,bytes=string.char(4,0,0,0)}}
   end
  end
  record.edits={}
  if crosshair_settings.handling then
   for _,edit in ipairs(record.base_edits) do record.edits[#record.edits+1]=edit end
  end
  if crosshair_settings[record.crosshair_key] then
   for _,edit in ipairs(record.crosshair_edits) do record.edits[#record.edits+1]=edit end
  end
  local target=record.original
  for _,edit in ipairs(record.edits) do target=splice(target,edit.offset,edit.bytes) end
  record.target=target
 end
end
crosshair_targets()

local ok,problem=pcall(function()
 assert(loader and loader.api==1, 'Bingus Shared Loader API 1 required')
