 local function pointer(address) return api.pointer(api.read(address,8)) end
 local function map_matches(address)
  if not address or api.read(address,32)~=reference_map:sub(1,32) then return false end
  for offset=0,#reference_map-1,2048 do
   local chunk=reference_map:sub(offset+1,offset+2048)
   if api.read(address+offset,#chunk)~=chunk then return false end
  end
  return true
 end
 local function read_record(at,size)
  local pieces={}
  for o=0,size-1,2048 do
   local chunk=api.read(at+o,math.min(2048,size-o))
   if not chunk then return nil end
   pieces[#pieces+1]=chunk
  end
  return table.concat(pieces)
 end
 local function rows_match(table_at,expected)
  for _,r in ipairs(records) do
   local at=table_at+#reference_map+r.index*1232
   if read_record(at,1232)~=r[expected] then return false end
  end
  return true
 end
 local function context(hit)
  return pointer(game+hit.owner.rva)==hit.owner.address
   and pointer(hit.owner.address+hit.slot_rva)==hit.table
   and map_matches(hit.table)
 end
 local function restore(hit)
  if not context(hit) then return false end
  for i=#records,1,-1 do
   local r=records[i]
   local at=hit.table+#reference_map+r.index*1232
   local row=read_record(at,1232)
   local prefix=r.original
   local applied=row==prefix and 0 or nil
   for j,edit in ipairs(r.edits) do
    prefix=splice(prefix,edit.offset,edit.bytes)
    if row==prefix then applied=j end
   end
   if applied==nil then return false end
   for j=applied,1,-1 do
    local edit=r.edits[j]
    local original=r.original:sub(edit.offset+1,edit.offset+#edit.bytes)
    if not api.write(at+edit.offset,original) then return false end
    row=splice(row,edit.offset,original)
    if read_record(at,1232)~=row then return false end
   end
  end
  return rows_match(hit.table,'original')
 end
 local function apply(hit)
  if not context(hit) or not rows_match(hit.table,'original') then
   state.status='BASELINE_MISMATCH_NO_WRITE';return
  end
  local function fail(reason)
   state.status=restore(hit) and reason..'_ROLLED_BACK' or reason..'_RESTORE_NOT_CONFIRMED'
  end
  for _,r in ipairs(records) do
   local at=hit.table+#reference_map+r.index*1232
   local row=r.original
   for _,edit in ipairs(r.edits) do
    if not context(hit) or read_record(at,1232)~=row or not api.write(at+edit.offset,edit.bytes) then
     fail('WRITE_FAILED');return
    end
    row=splice(row,edit.offset,edit.bytes)
    state.writes=state.writes+1
    if read_record(at,1232)~=row then fail('READBACK_MISMATCH');return end
   end
  end
  state.active=hit
  state.status='APPLIED_WEAPON'
 end
