  end
  if state.status=='LOCATING_ENTITY_OWNER' or state.status=='SCANNING_TABLES' then
   local good,err=pcall(function()
    if state.status=='LOCATING_ENTITY_OWNER' then
     resolver:step()
     if resolver.status:find('^COMPLETE') then
      owners={}
      for _,candidate in ipairs(resolver.candidates) do
       if candidate.kind=='ENTITY_OWNER' then owners[#owners+1]=candidate end
      end
      if #owners==0 then state.status='NO_ENTITY_OWNER_NO_WRITE'
      else state.status='SCANNING_TABLES' end
     elseif resolver.status=='ERROR' then state.status='ENTITY_OWNER_ERROR_NO_WRITE' end
    else
     local owner=owners[owner_index]
     if not owner then state.status='NO_ENTITY_OWNER_NO_WRITE';return end
     for _=1,8 do
      if slot_index>=1536 then next_owner();return end
      local slot_rva=0xF10000+slot_index*8
      slot_index=slot_index+1;state.checked=state.checked+1
      local table_at=pointer(owner.address+slot_rva)
